import { OrderRepository } from '../domain/repositories';
import { OrderState } from '../domain/types';
import { OrderListResponse, OrderResponse } from './dtos';

export class ListOrdersUseCase {
  constructor(private orderRepo: OrderRepository) {}

  executeByState(state: OrderState): OrderListResponse {
    const orders = this.orderRepo.getByState(state);
    return {
      orders: orders.map(order => this.mapToResponse(order)),
    };
  }

  executeAll(): OrderListResponse {
    const orders = this.orderRepo.getAll();
    return {
      orders: orders.map(order => this.mapToResponse(order)),
    };
  }

  private mapToResponse(order: any): OrderResponse {
    return {
      id: order.id,
      customerId: order.customerId,
      items: order.items,
      state: order.state,
      createdAt: order.createdAt.toISOString(),
      updatedAt: order.updatedAt.toISOString(),
    };
  }
}

